package com.github.tartaricacid.touhoulittlemaid.item.enchantment;
import com.github.tartaricacid.touhoulittlemaid.item.ItemHakureiGohei;import net.minecraft.enchantment.Enchantment;import net.minecraft.enchantment.EnumEnchantmentType;import net.minecraft.item.ItemStack;
public final class EnchantmentGohei extends Enchantment{public enum Type{IMPEDING,SPEEDY,ENDERS_ENDER}private final Type type;public EnchantmentGohei(int id,String name,Type type,int weight){super(id,weight,EnumEnchantmentType.weapon);this.type=type;setName("touhou_little_maid."+name);}@Override public int getMaxLevel(){return type==Type.IMPEDING?4:type==Type.SPEEDY?2:1;}@Override public int getMinEnchantability(int level){return type==Type.IMPEDING?10+(level-1)*8:type==Type.SPEEDY?15+level*10:20;}@Override public int getMaxEnchantability(int level){return getMinEnchantability(level)+30;}@Override public boolean canApply(ItemStack stack){return stack!=null&&stack.getItem() instanceof ItemHakureiGohei;}public Type getType(){return type;}}
